ll modpow(ll a, ll e) {
    ll res = 1;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

void init_fact() {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i-1] * i % MOD;
    invfact[n] = modpow(fact[n], MOD-2);
    for (int i = n; i >= 1; i--) invfact[i-1] = invfact[i] * i % MOD;
}

ll C(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD;
}

void dfs(int u, int p) {
    sz[u] = 1;
    for (int i = head[u]; i != -1; i = nxt[i]) {
        int v = to[i];
        if (v == p) continue;
        dfs(v, u);
        sz[u] += sz[v];
    }
}

void compute(int u, int p) {
    // total subsets of size K that include u = C(n, K) - sum over components C(comp_size, K)
    for (int k = 1; k <= n; k++) {
        ll total = C(n, k);
        // components from children
        for (int i = head[u]; i != -1; i = nxt[i]) {
            int v = to[i];
            if (v == p) continue;
            total = (total - C(sz[v], k) + MOD) % MOD;
        }
        // component from parent side
        total = (total - C(n - sz[u], k) + MOD) % MOD;
        ans[k] = (ans[k] + total) % MOD;
    }
    for (int i = head[u]; i != -1; i = nxt[i]) {
        int v = to[i];
        if (v == p) continue;
        compute(v, u);
    }
}

