#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 924844033LL

typedef long long ll;

typedef struct Edge {
    int to, next;
} Edge;

static ll mod_pow(ll a, ll e) {
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Edge *edges = (Edge *)malloc(sizeof(Edge) * (2 * (N - 1)));
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    int *deg = (int *)calloc(N + 1, sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        edges[ecnt].to = b; edges[ecnt].next = head[a]; head[a] = ecnt++;
        edges[ecnt].to = a; edges[ecnt].next = head[b]; head[b] = ecnt++;
        deg[a]++; deg[b]++;
    }

    /* Root tree at 1, get parent and order */
    int *parent = (int *)malloc(sizeof(int) * (N + 1));
    int *order = (int *)malloc(sizeof(int) * N);
    int *stack = (int *)malloc(sizeof(int) * N);
    int top = 0, ordsz = 0;
    stack[top++] = 1;
    parent[1] = 0;

    while (top) {
        int v = stack[--top];
        order[ordsz++] = v;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            if (u == parent[v]) continue;
            parent[u] = v;
            stack[top++] = u;
        }
    }

    /* subtree sizes */
    int *sz = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 1; i <= N; i++) sz[i] = 1;
    for (int i = N - 1; i > 0; i--) {
        int v = order[i];
        sz[parent[v]] += sz[v];
    }

    /* factorials and invfactorials */
    ll *fact = (ll *)malloc(sizeof(ll) * (N + 1));
    ll *invfact = (ll *)malloc(sizeof(ll) * (N + 1));
    fact[0] = 1;
    for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[N] = mod_pow(fact[N], MOD - 2);
    for (int i = N; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    /* C(n,k) for fixed k can be updated incrementally:
       C(x,k) from C(x-1,k): C(x,k)=C(x-1,k)*x/(x-k)
       but simpler to use fact/invfact in O(1).
    */

    ll *ans = (ll *)calloc(N + 1, sizeof(ll));

    /* For each k:
       Sum_S f(S) = sum_v count of k-sets whose Steiner tree contains v
       For rooted tree, v is in Steiner tree iff selected vertices are not all contained in one component of T-v.
       So contribution of v:
         C(N,k) - sum over components c of T-v of C(|c|,k)
       Components sizes after removing v:
         each child subtree size sz[u], and the "parent side" N-sz[v] (if v!=1)
    */
    for (int k = 1; k <= N; k++) {
        ll total = 0;
        ll all = 0;
        if (k <= N) {
            all = fact[N] * invfact[k] % MOD * invfact[N - k] % MOD;
        }

        for (int v = 1; v <= N; v++) {
            ll bad = 0;
            for (int e = head[v]; e != -1; e = edges[e].next) {
                int u = edges[e].to;
                int comp;
                if (u == parent[v]) comp = N - sz[v];
                else comp = sz[u];
                if (comp >= k) {
                    ll ways = fact[comp] * invfact[k] % MOD * invfact[comp - k] % MOD;
                    bad += ways;
                    if (bad >= MOD) bad -= MOD;
                }
            }
            ll cur = all - bad;
            if (cur < 0) cur += MOD;
            total += cur;
            if (total >= MOD) total -= MOD;
        }
        ans[k] = total;
    }

    for (int k = 1; k <= N; k++) {
        if (k > 1) putchar(' ');
        printf("%lld", ans[k] % MOD);
    }
    putchar('\n');

    free(edges);
    free(head);
    free(deg);
    free(parent);
    free(order);
    free(stack);
    free(sz);
    free(fact);
    free(invfact);
    free(ans);
    return 0;
}

