// precompute factorials, then for each edge get subtree size s, accumulate poly coefficients
// Answer(K) = N*C(N,K) - sum_edges [C(s,K)+C(N-s,K)]

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 924844033LL;

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<vector<int>> g(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    // Precompute factorials and inverse factorials
    vector<long long> fact(N + 1), ifact(N + 1);
    fact[0] = 1;
    for (int i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;
    ifact[N] = modpow(fact[N], MOD - 2);
    for (int i = N; i >= 1; --i) ifact[i - 1] = ifact[i] * i % MOD;

    auto C = [&](int n, int k) -> long long {
        if (k < 0 || k > n) return 0;
        return fact[n] * ifact[k] % MOD * ifact[n - k] % MOD;
    };

    vector<int> parent(N + 1, 0), order;
    order.reserve(N);
    stack<int> st;
    st.push(1);
    parent[1] = -1;
    while (!st.empty()) {
        int v = st.top();
        st.pop();
        order.push_back(v);
        for (int to : g[v]) {
            if (to == parent[v]) continue;
            parent[to] = v;
            st.push(to);
        }
    }

    vector<int> sz(N + 1, 1);
    for (int i = N - 1; i >= 0; --i) {
        int v = order[i];
        for (int to : g[v]) {
            if (to == parent[v]) continue;
            sz[v] += sz[to];
        }
    }

    // ans[k] = sum over all |S|=k of f(S)
    // Count contribution of each vertex v:
    // v belongs to Steiner tree of S iff S intersects at least two components
    // of T-v, or S contains v.
    //
    // Easier via complement:
    // v is NOT in minimal subtree containing S iff all chosen vertices lie
    // entirely inside one component of T-v.
    //
    // Components of T-v have sizes:
    // for each child to: sz[to]
    // plus parent side: N - sz[v] (if v != root)
    //
    // Therefore number of k-subsets whose Steiner tree contains v:
    // C(N,k) - sum_components C(comp_size, k)
    // but subsets {v}?? Actually if S={v}, contains v yes, formula gives C(N,1)-sum comp = 1.
    // Correct for all k>=1.
    vector<long long> ans(N + 1, 0);
    for (int v = 1; v <= N; ++v) {
        vector<int> comps;
        for (int to : g[v]) {
            if (to == parent[v]) continue;
            comps.push_back(sz[to]);
        }
        if (parent[v] != -1) comps.push_back(N - sz[v]);

        for (int k = 1; k <= N; ++k) {
            long long cur = C(N, k);
            for (int c : comps) {
                cur -= C(c, k);
                if (cur < 0) cur += MOD;
            }
            ans[k] += cur;
            if (ans[k] >= MOD) ans[k] -= MOD;
        }
    }

    for (int k = 1; k <= N; ++k) {
        cout << ans[k] % MOD << '\n';
    }

    return 0;
}

