public class Main {
    static final int MOD = 924844033;
    static long[] fact, invFact;

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    static long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        List<Integer>[] adj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < N - 1; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            adj[a].add(b);
            adj[b].add(a);
        }

        fact = new long[N + 1];
        invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N - 1; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % MOD;

        int[] sz = new int[N + 1];
        long[][] compSizes = new long[N + 1][];
        dfs(1, 0, adj, sz, compSizes);

        long[] ans = new long[N + 1];
        long[] combN = new long[N + 1];
        for (int k = 1; k <= N; k++) {
            combN[k] = comb(N, k);
        }

        for (int v = 1; v <= N; v++) {
            long[] comp = compSizes[v];
            for (int k = 1; k <= N; k++) {
                long total = combN[k];
                for (long s : comp) {
                    total = (total - comb((int)s, k) + MOD) % MOD;
                }
                ans[k] = (ans[k] + total) % MOD;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int k = 1; k <= N; k++) {
            sb.append(ans[k]).append('\n');
        }
        System.out.print(sb);
    }

    static int dfs(int u, int p, List<Integer>[] adj, int[] sz, long[][] compSizes) {
        sz[u] = 1;
        List<Long> comps = new ArrayList<>();
        for (int v : adj[u]) {
            if (v == p) continue;
            int childSize = dfs(v, u, adj, sz, compSizes);
            comps.add((long) childSize);
            sz[u] += childSize;
        }
        if (p != 0) {
            comps.add((long) (adj.length - 1 - sz[u] + 1));
        }
        long[] arr = new long[comps.size()];
        for (int i = 0; i < arr.length; i++) arr[i] = comps.get(i);
        compSizes[u] = arr;
        return sz[u];
    }
}

