public class Main {
    static final int MOD = 924844033;
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= N; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < N-1; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken()), b = Integer.parseInt(st.nextToken());
            adj.get(a).add(b); adj.get(b).add(a);
        }
        int[] sz = new int[N+1];
        Arrays.fill(sz, 1);
        int[] parent = new int[N+1];
        int[] order = new int[N];
        boolean[] visited = new boolean[N+1];
        int head = 0, tail = 0;
        order[tail++] = 1; visited[1] = true; parent[1] = 0;
        while (head < tail) { int u = order[head++]; for (int v : adj.get(u)) if (!visited[v]) { visited[v]=true; parent[v]=u; order[tail++]=v; } }
        for (int i = N-1; i >= 1; i--) { int u = order[i]; sz[parent[u]] += sz[u]; }
        long[] C = new long[N+1]; // C[k] = sum of C(p_e,k)+C(N-p_e,k) over edges
        long[] fact = new long[N+1], inv_fact = new long[N+1];
        fact[0]=1; for(int i=1;i<=N;i++) fact[i]=fact[i-1]*i%MOD;
        inv_fact[N]=modpow(fact[N],MOD-2,MOD); for(int i=N-1;i>=0;i--) inv_fact[i]=inv_fact[i+1]*(i+1)%MOD;
        // For each edge, add C(sz[v],k)+C(N-sz[v],k) for all k
        long[] edgeContrib = new long[N+1];
        for (int i = 1; i < N; i++) { int v = order[i]; int p = sz[v]; edgeContrib[p]++; edgeContrib[N-p]++; }
        // Now answer[k] = N*C(N,k) - sum_k edgeContrib[p]*C(p,k)
        // We need sum over p of edgeContrib[p]*C(p,k)
        // = sum_p edgeContrib[p] * fact[p]/(fact[k]*fact[p-k])
        // Use generating functions or direct computation
        long[] ans = new long[N+1];
        for (int p = 1; p <= N; p++) { if (edgeContrib[p]==0) continue; for (int k=1;k<=p;k++) { ans[k]=(ans[k]+edgeContrib[p]%MOD*comb(fact,inv_fact,p,k))%MOD; } }
        StringBuilder sb = new StringBuilder();
        for (int k=1;k<=N;k++) { long a=(long)N%MOD*comb(fact,inv_fact,N,k)%MOD-ans[k]+MOD; sb.append(a%MOD).append('\n'); }
        System.out.print(sb);
    }
    static long comb(long[] f, long[] fi, int n, int k) { if(k<0||k>n) return 0; return f[n]*fi[k]%MOD*fi[n-k]%MOD; }
    static long modpow(long b, long e, long m) { long r=1; b%=m; while(e>0){if((e&1)==1)r=r*b%m;b=b*b%m;e>>=1;} return r; }
}

